def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]

    for color in set(v for row in grid for v in row):
        points = {(r, c) for r in range(h) for c in range(w)
                  if grid[r][c] == color}
        for r, c in points:
            for dr, dc in ((1, 1), (1, -1), (-1, 1), (-1, -1)):
                nr, nc = r + dr, c + dc
                if (nr, nc) not in points:
                    continue
                # Continue the diagonal beyond the second adjacent marker.
                rr, cc = nr + dr, nc + dc
                while 0 <= rr < h and 0 <= cc < w:
                    if grid[rr][cc] != background:
                        break
                    out[rr][cc] = color
                    rr += dr
                    cc += dc
    return out
